using System;
using System.IO;
using System.Collections.Generic;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using CoopBeam;
public static class CandyPixelStyle {
 public const string Art="Assets/ReinoDeChicle/0_3_Art/PixelArt/";
 static readonly string[] Characters={"Coral","Celeste","CandyWalker","GummyJumper","ToffeeChaser","CocoaGuard","FlyingGummy","SugarCannon","KingBubble"};
 static readonly string[] Enemies={"CandyWalker","GummyJumper","ToffeeChaser","CocoaGuard","FlyingGummy","SugarCannon","KingBubble"};
 public static bool Available=>File.Exists(Art+"Characters/CandyWalker.png");
 static Sprite mote,core,candy;static Sprite[] tiles;static Material characterMaterial;
 [MenuItem("Coop Beam/Apply Pixel Art and Candy Startup")]
 public static void Apply(){if(EditorApplication.isPlaying)throw new Exception("Exit Play before applying assets");EditorSceneManager.SaveOpenScenes();Directory.CreateDirectory(Art+"Tiles");AssetDatabase.Refresh();
  foreach(string name in Characters){string path=Art+"Characters/"+name+".png";if(!File.Exists(path))throw new Exception("Missing generated sprite "+path);Import(path,name=="Coral"||name=="Celeste"?1.3f:1);}
  for(int i=1;i<=5;i++){string path=Art+"Backgrounds/Background_0"+i+".png";if(!File.Exists(path))throw new Exception("Missing generated backdrop "+path);Import(path,1);}
  characterMaterial=AssetDatabase.LoadAssetAtPath<Material>(Art+"PixelCharacters.mat");if(!characterMaterial){characterMaterial=new Material(Shader.Find("CoopBeam/PixelSprite"));AssetDatabase.CreateAsset(characterMaterial,Art+"PixelCharacters.mat");}
  tiles=new Sprite[5];for(int i=0;i<5;i++)tiles[i]=MakeTile(i);mote=MakeIcon("PixelSpark",0);core=MakeIcon("MintCore",1);candy=MakeIcon("SugarPearl",2);var lollipop=MakeIcon("Lollipop",3);
  for(int i=0;i<2;i++){string path="Assets/Prototype_CoopBeam/0_2_Prefabs/"+Characters[i]+".prefab";var root=PrefabUtility.LoadPrefabContents(path);try{var pc=root.GetComponent<PlayerController2D>();pc.visual.localPosition=new Vector3(0,.1f,0);pc.sprite.sharedMaterial=characterMaterial;pc.sprite.sprite=AssetDatabase.LoadAssetAtPath<Sprite>(Art+"Characters/"+Characters[i]+".png");pc.visual.localScale=Vector3.one;AlignFeet(pc.sprite,pc.visual,root.GetComponent<CapsuleCollider2D>().size.y*.5f);if(!pc.visual.GetComponent<PixelActorVisual>())pc.visual.gameObject.AddComponent<PixelActorVisual>();PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}}
  foreach(string name in Enemies){string path="Assets/ReinoDeChicle/0_2_Prefabs/"+name+".prefab";var root=PrefabUtility.LoadPrefabContents(path);try{var enemy=root.GetComponent<EnemyBase>();enemy.sprite.sharedMaterial=characterMaterial;enemy.sprite.sprite=AssetDatabase.LoadAssetAtPath<Sprite>(Art+"Characters/"+name+".png");if(enemy.kind!=EnemyKind.Flyer)AlignFeet(enemy.sprite,enemy.visual,enemy.kind==EnemyKind.Boss?1.4f:root.GetComponent<CapsuleCollider2D>().size.y*.5f);if(!enemy.visual.GetComponent<PixelActorVisual>())enemy.visual.gameObject.AddComponent<PixelActorVisual>();var special=root.GetComponent<CandyEnemySpecial>();if(special){special.projectile=candy;var r=special.telegraph.GetComponent<SpriteRenderer>();r.sprite=mote;}var boss=root.GetComponent<CandyBoss>();if(boss){boss.projectile=candy;boss.weakArt.sprite=core;}PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}}
  for(int n=1;n<=5;n++){var scene=EditorSceneManager.OpenScene(CandyCampaign.ScenePath(n));var manager=UnityEngine.Object.FindAnyObjectByType<GameManager>();manager.particle=mote;var oldUI=UnityEngine.Object.FindAnyObjectByType<UIManager>();if(oldUI)UnityEngine.Object.DestroyImmediate(oldUI);var hud=UnityEngine.Object.FindAnyObjectByType<CandyPixelHUD>();if(!hud)hud=new GameObject("Pixel arcade HUD").AddComponent<CandyPixelHUD>();hud.game=manager;
   foreach(var cam in UnityEngine.Object.FindObjectsByType<Camera>()){if(!cam.GetComponent<PixelViewport>())cam.gameObject.AddComponent<PixelViewport>();cam.GetComponent<PixelViewport>().paletteShader=Shader.Find("Hidden/CoopBeam/PixelPalette");}
   foreach(var sr in UnityEngine.Object.FindObjectsByType<SpriteRenderer>()){
    if(sr.name=="Original candy backdrop"){sr.sprite=AssetDatabase.LoadAssetAtPath<Sprite>(Art+"Backgrounds/Background_0"+n+".png");sr.transform.localScale=new Vector3(26/sr.sprite.bounds.size.x,15/sr.sprite.bounds.size.y,1);sr.color=new Color(.82f,.78f,.88f);}
    else if(sr.name=="Candy platform art"){var root=sr.transform.parent;var surface=root.GetComponent<CandyEnvironment>();int style=surface?surface.kind==CandySurfaceKind.Bounce?1:surface.kind==CandySurfaceKind.Conveyor?4:surface.kind==CandySurfaceKind.Crumbly?2:root.name.Contains("marshmallow")?2:0:root.name.Contains("cocoa")||root.name.Contains("Chocolate")||root.name.Contains("machine")?3:root.name.Contains("Gummy")||root.name.Contains("Mint")?1:0;sr.sprite=tiles[style];sr.transform.localScale=Vector3.one;sr.drawMode=SpriteDrawMode.Tiled;sr.tileMode=SpriteTileMode.Continuous;sr.size=root.GetComponent<BoxCollider2D>().size;}
    else if(sr.name=="Lollipop")sr.sprite=lollipop;
    else if(sr.name=="Candy cane stem")sr.sprite=tiles[0];
    else if(sr.name=="Animated press")sr.sprite=tiles[3];
   }
   EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
  }
  var mapScene=EditorSceneManager.OpenScene(CandyCampaign.Root+"Candy_WorldMap.unity");var map=UnityEngine.Object.FindAnyObjectByType<CandyWorldMap>();map.backdrop=AssetDatabase.LoadAssetAtPath<Texture2D>(Art+"Backgrounds/Background_01.png");if(File.Exists(Art+"CandyLogo.png")){Import(Art+"CandyLogo.png",1);map.logo=AssetDatabase.LoadAssetAtPath<Texture2D>(Art+"CandyLogo.png");}foreach(var cam in UnityEngine.Object.FindObjectsByType<Camera>()){if(!cam.GetComponent<PixelViewport>())cam.gameObject.AddComponent<PixelViewport>();cam.GetComponent<PixelViewport>().paletteShader=Shader.Find("Hidden/CoopBeam/PixelPalette");}var mapBg=GameObject.Find("PixelMapBackground");if(!mapBg)mapBg=new GameObject("PixelMapBackground");var bg=mapBg.GetComponent<SpriteRenderer>();if(!bg)bg=mapBg.AddComponent<SpriteRenderer>();bg.sprite=AssetDatabase.LoadAssetAtPath<Sprite>(Art+"Backgrounds/Background_01.png");bg.sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/Prototype_CoopBeam/0_3_Art/SpriteUnlit.mat");bg.color=new Color(.7f,.6f,.8f);bg.sortingOrder=-30;mapBg.transform.position=new Vector3(0,1,0);mapBg.transform.localScale=new Vector3(26/bg.sprite.bounds.size.x,15/bg.sprite.bounds.size.y,1);EditorSceneManager.MarkSceneDirty(mapScene);EditorSceneManager.SaveScene(mapScene);
  // The executable starts in Candy; Editor Play respects the scene selected by the developer.
  var builds=new List<EditorBuildSettingsScene>{new EditorBuildSettingsScene(CandyCampaign.ScenePath(1),true),new EditorBuildSettingsScene(CandyCampaign.Root+"Candy_WorldMap.unity",true)};for(int n=2;n<=5;n++)builds.Add(new EditorBuildSettingsScene(CandyCampaign.ScenePath(n),true));EditorBuildSettings.scenes=builds.ToArray();EditorSceneManager.playModeStartScene=null;AssetDatabase.SaveAssets();EditorSceneManager.OpenScene(CandyCampaign.ScenePath(1));if(CandyAnimationPolish.Available)CandyAnimationPolish.Apply();Debug.Log("CANDY_PIXEL_STYLE_OK: 9 generated characters, 5 generated backdrops, pixel tiles/HUD and candy startup.");
 }
 static void Import(string path,float units){var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.textureType=TextureImporterType.Sprite;imp.spriteImportMode=SpriteImportMode.Single;var settings=new TextureImporterSettings();imp.ReadTextureSettings(settings);settings.spriteMeshType=SpriteMeshType.FullRect;imp.SetTextureSettings(settings);imp.filterMode=FilterMode.Point;imp.mipmapEnabled=false;imp.textureCompression=TextureImporterCompression.Uncompressed;imp.maxTextureSize=2048;imp.npotScale=TextureImporterNPOTScale.None;imp.alphaIsTransparency=true;imp.wrapMode=TextureWrapMode.Clamp;var texture=AssetDatabase.LoadAssetAtPath<Texture2D>(path);imp.spritePixelsPerUnit=texture.width/units;imp.SaveAndReimport();}
 static void AlignFeet(SpriteRenderer renderer,Transform visual,float halfHeight){var texture=new Texture2D(2,2,TextureFormat.RGBA32,false);texture.LoadImage(File.ReadAllBytes(AssetDatabase.GetAssetPath(renderer.sprite)));var pixels=texture.GetPixels32();int bottom=texture.height;for(int y=0;y<texture.height;y++){bool found=false;for(int x=0;x<texture.width;x++)if(pixels[y*texture.width+x].a>40){bottom=y;found=true;break;}if(found)break;}float offset=-halfHeight-(bottom-texture.height*.5f)/renderer.sprite.pixelsPerUnit*visual.localScale.y;visual.localPosition=new Vector3(0,offset,0);UnityEngine.Object.DestroyImmediate(texture);}
 static Color Hex(string s){ColorUtility.TryParseHtmlString("#"+s,out Color c);return c;}
 static Sprite Save(string name,Texture2D t,int ppu){t.Apply();string path=Art+"Tiles/"+name+".png";File.WriteAllBytes(path,t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);AssetDatabase.ImportAsset(path);Import(path,1);var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.spritePixelsPerUnit=ppu;imp.wrapMode=TextureWrapMode.Repeat;imp.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Sprite>(path);}
 static Sprite MakeTile(int kind){var t=new Texture2D(32,16,TextureFormat.RGBA32,false);Color[] body={Hex("D779A0"),Hex("4EBFA4"),Hex("EAD4BA"),Hex("65405D"),Hex("AF7F54")};for(int y=0;y<16;y++)for(int x=0;x<32;x++){Color c=body[kind];if(y<2)c=Hex("39253E");else if(y==2)c=Color.Lerp(body[kind],Hex("39253E"),.5f);else if(y>=12+(x/4%2))c=kind==3?Hex("B36B83"):Hex("FFF0CE");else if(kind==3&&(x%8==0||y==7))c=Hex("442C49");else if(kind==4&&((x+y)%12)<4)c=Hex("4F344B");else if(kind==1&&y==9&&x%8<5)c=Hex("94EBC5");else if((x*7+y*11)%53<2)c=kind==2?Hex("D4A4BE"):Hex("F9CE7A");t.SetPixel(x,y,c);}return Save(new[]{"Caramel","Gummy","Marshmallow","Chocolate","Conveyor"}[kind],t,32);}
 static Sprite MakeIcon(string name,int kind){var t=new Texture2D(16,16,TextureFormat.RGBA32,false);for(int y=0;y<16;y++)for(int x=0;x<16;x++){int dx=Mathf.Abs(x-7),dy=Mathf.Abs(y-7);Color c=Color.clear;if(kind==0){if((dx<=1&&dy<6)||(dy<=1&&dx<6))c=Color.white;}else if(dx+dy<11&&dx<7&&dy<7){if(kind==1)c=dx+dy>8?Hex("234B55"):dx+dy>5?Hex("54CBA7"):Hex("D2FFDA");else c=(x+y)/3%2==0?Hex("FFEAC7"):kind==3?Hex("E879AF"):Hex("E98CA8");if((x==4||x==5)&&y>8&&y<12)c=Hex("FFF6E4");}t.SetPixel(x,y,c);}return Save(name,t,16);}
}






